import { demoWorkspace } from './demoWorkspace'
import type {
  AccessRule,
  ChangeResolution,
  CorrectionScope,
  MemoryCategory,
  MemoryChange,
  MemoryCorrection,
  MemoryItem,
  MemoryRepository,
  MemoryTension,
  MemoryWorkspace,
  TensionResolution,
} from '../domain/memory'

const cloneWorkspace = () => structuredClone(demoWorkspace)

export class MockMemoryRepository implements MemoryRepository {
  private workspace = cloneWorkspace()

  async loadWorkspace(): Promise<MemoryWorkspace> {
    return structuredClone(this.workspace)
  }

  async resolveChange(id: string, _action: ChangeResolution): Promise<MemoryChange> {
    const change = this.workspace.changes.find((item) => item.id === id)
    if (!change) throw new Error(`Unknown change: ${id}`)
    change.status = 'resolved'
    return structuredClone(change)
  }

  async setPinned(id: string, pinned: boolean): Promise<MemoryItem> {
    const memory = this.workspace.memories.find((item) => item.id === id)
    if (!memory) throw new Error(`Unknown memory: ${id}`)
    memory.pinned = pinned
    return structuredClone(memory)
  }

  async resolveTension(id: string, action: TensionResolution): Promise<MemoryTension> {
    const tension = this.workspace.tensions.find((item) => item.id === id)
    if (!tension) throw new Error(`Unknown tension: ${id}`)
    tension.status = 'resolved'
    tension.resolution = action
    return structuredClone(tension)
  }

  async applyCorrection(id: string, scope: CorrectionScope): Promise<MemoryCorrection> {
    const correction = this.workspace.correction
    if (correction.id !== id) throw new Error(`Unknown correction: ${id}`)
    correction.scope = scope
    correction.status = scope === 'ignore' ? 'ignored' : 'applied'
    return structuredClone(correction)
  }

  async updateAccess(appId: string, category: MemoryCategory, enabled: boolean): Promise<AccessRule> {
    const rule = this.workspace.accessRules.find((item) => item.appId === appId && item.category === category)
    if (!rule) throw new Error(`Unknown access rule: ${appId}/${category}`)
    rule.enabled = enabled
    return structuredClone(rule)
  }

  async resetDemo(): Promise<MemoryWorkspace> {
    this.workspace = cloneWorkspace()
    return this.loadWorkspace()
  }
}

// oxlint-disable react/only-export-components -- the typed hook is the provider's public boundary.
import { createContext, useCallback, useContext, useEffect, useState, type ReactNode } from 'react'
import { MockMemoryRepository } from '../data/mockMemoryRepository'
import type { ChangeResolution, CorrectionScope, MemoryCategory, MemoryRepository, MemoryWorkspace, TensionResolution } from '../domain/memory'

interface MemoryContextValue {
  workspace: MemoryWorkspace
  repository: MemoryRepository
  performanceMode: boolean
  setPerformanceMode: (value: boolean) => void
  refresh: () => Promise<void>
  resolveChange: (id: string, action: ChangeResolution) => Promise<void>
  setPinned: (id: string, pinned: boolean) => Promise<void>
  resolveTension: (id: string, action: TensionResolution) => Promise<void>
  applyCorrection: (id: string, scope: CorrectionScope) => Promise<void>
  updateAccess: (appId: string, category: MemoryCategory, enabled: boolean) => Promise<void>
  resetDemo: () => Promise<void>
  toast: string | null
}

const MemoryContext = createContext<MemoryContextValue | null>(null)

export function MemoryProvider({ children }: { children: ReactNode }) {
  const [repository] = useState<MemoryRepository>(() => new MockMemoryRepository())
  const [workspace, setWorkspace] = useState<MemoryWorkspace | null>(null)
  const [performanceMode, setPerformanceMode] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [toast, setToast] = useState<string | null>(null)

  const refresh = useCallback(async () => {
    try {
      setError(null)
      setWorkspace(await repository.loadWorkspace())
    } catch {
      setError('기억을 불러오지 못했습니다.')
    }
  }, [repository])

  useEffect(() => { void refresh() }, [refresh])

  const run = async (operation: () => Promise<unknown>, message?: string) => {
    try {
      await operation()
      await refresh()
      if (message) setToast(message)
    } catch {
      setToast('변경을 저장하지 못했습니다. 다시 시도해 주세요.')
    }
  }

  const actions = {
    resolveChange: (id: string, action: ChangeResolution) => run(() => repository.resolveChange(id, action), '기억을 업데이트했습니다.'),
    setPinned: (id: string, pinned: boolean) => run(() => repository.setPinned(id, pinned)),
    resolveTension: (id: string, action: TensionResolution) => run(() => repository.resolveTension(id, action), action === 'conditional' ? '조건부 기억으로 분리했습니다.' : '선택한 기억만 남겼습니다.'),
    applyCorrection: (id: string, scope: CorrectionScope) => run(() => repository.applyCorrection(id, scope), scope === 'global' ? '모든 대화에 반영했습니다.' : scope === 'conversation' ? '이 대화에만 반영했습니다.' : '수정 제안을 무시했습니다.'),
    updateAccess: (appId: string, category: MemoryCategory, enabled: boolean) => run(() => repository.updateAccess(appId, category, enabled)),
    resetDemo: () => run(() => repository.resetDemo(), '데모 데이터를 초기 상태로 되돌렸습니다.'),
  }

  const value = workspace ? ({ workspace, repository, performanceMode, setPerformanceMode, refresh, toast, ...actions }) : null

  if (error) return <main><p>{error}</p><button onClick={() => void refresh()}>다시 시도</button></main>
  if (!value) return <div aria-label="기억 불러오는 중" role="status" />
  return <MemoryContext.Provider value={value}>{children}</MemoryContext.Provider>
}

export function useMemory() {
  const value = useContext(MemoryContext)
  if (!value) throw new Error('useMemory must be used inside MemoryProvider')
  return value
}

export type MemoryCategory = '코딩' | '일' | '취향' | '개인'
export type MemoryState = 'strong' | 'fading' | 'review' | 'archived'
export type ChangeResolution = 'accept' | 'reject' | 'archive' | 'keep'
export type TensionResolution = 'conditional' | 'keep-one'
export type CorrectionScope = 'global' | 'conversation' | 'ignore'

export interface MemoryItem {
  id: string
  text: string
  category: MemoryCategory
  ageBucket: 'now' | '30d' | '90d' | '1y' | 'archive'
  ageLabel: string
  strength: number
  usageCount: number
  pinned: boolean
  state: MemoryState
}

export interface MemoryChange {
  id: string
  kind: 'changed' | 'fading' | 'duplicate' | 'contradiction'
  meta: string
  title: string
  description: string
  confidence: number
  status: 'pending' | 'resolved'
  before?: string
  after?: string
  evidence: string[]
}

export interface MemoryTension {
  id: string
  left: string
  right: string
  status: 'pending' | 'resolved'
  resolution?: TensionResolution
  rules: Array<{ context: string; priority: string }>
}

export interface ManualSection {
  id: string
  eyebrow: string
  text: string
  changedPhrase?: string
  evidence: string[]
  review?: boolean
}

export interface OrbitQuestion {
  id: string
  question: string
  answer: string
  answerCards: [string, string, string]
  meta: string
}

export interface MemoryCorrection {
  id: string
  before: string
  after: string
  status: 'pending' | 'applied' | 'ignored'
  scope?: CorrectionScope
}

export interface AccessRule {
  appId: string
  appName: string
  category: MemoryCategory
  enabled: boolean
}

export interface MemoryWorkspace {
  memoryCount: number
  week: { strengthened: number; archived: number; merged: number; pending: number }
  memories: MemoryItem[]
  changes: MemoryChange[]
  tensions: MemoryTension[]
  manual: ManualSection[]
  orbitQuestions: OrbitQuestion[]
  correction: MemoryCorrection
  accessRules: AccessRule[]
}

export interface MemoryRepository {
  loadWorkspace(): Promise<MemoryWorkspace>
  resolveChange(id: string, action: ChangeResolution): Promise<MemoryChange>
  setPinned(id: string, pinned: boolean): Promise<MemoryItem>
  resolveTension(id: string, action: TensionResolution): Promise<MemoryTension>
  applyCorrection(id: string, scope: CorrectionScope): Promise<MemoryCorrection>
  updateAccess(appId: string, category: MemoryCategory, enabled: boolean): Promise<AccessRule>
  resetDemo(): Promise<MemoryWorkspace>
}

.stats {
