import { ArrowRight, Check, Clock3, X } from '../icons'
import { useState } from 'react'
import { useLocation } from 'react-router-dom'
import type { MemoryChange } from '../domain/memory'
import { useMemory } from '../state/MemoryContext'
import screen from './Screen.module.css'
import styles from './ChangesPage.module.css'

const kindLabel: Record<MemoryChange['kind'], string> = {
  changed: 'CHANGED', fading: 'FADING', duplicate: 'DUPLICATE', contradiction: 'CONTRADICTION',
}

const weeks = ['8월 10일 — 8월 16일', '8월 3일 — 8월 9일', '7월 27일 — 8월 2일', '7월 20일 — 7월 26일']

export function ChangesPage() {
  const { workspace, resolveChange } = useMemory()
  const location = useLocation()
  const [modal, setModal] = useState<'diff' | 'review' | 'cleanup' | null>(() => (location.state as { openCleanup?: boolean } | null)?.openCleanup ? 'cleanup' : null)
  const [cleanupIndex, setCleanupIndex] = useState(0)
  const [showAll, setShowAll] = useState(false)
  const [showEvidence, setShowEvidence] = useState(false)
  const [selectedWeek, setSelectedWeek] = useState(weeks[0])
  const [weekPickerOpen, setWeekPickerOpen] = useState(false)
  const pending = workspace.changes.filter((item) => item.status === 'pending')
  const change = workspace.changes[0]
  const cleanup = workspace.memories.filter((item) => item.state === 'fading' || item.state === 'review').slice(0, 3)

  const advanceCleanup = () => {
    if (cleanupIndex >= cleanup.length - 1) { setModal(null); setCleanupIndex(0) }
    else setCleanupIndex((value) => value + 1)
  }

  return (
    <section className={screen.screen}>
      <div className={screen.inner}>
        <div className={screen.topRow}>
          <header>
            <div className={styles.weekControl}>
              <button
                className={screen.datePicker}
                aria-expanded={weekPickerOpen}
                aria-haspopup="listbox"
                aria-controls="changes-week-picker"
                onClick={() => setWeekPickerOpen((value) => !value)}
              >
                {selectedWeek}
              </button>
              {weekPickerOpen && <div id="changes-week-picker" className={styles.weekPicker} role="listbox" aria-label="Changes 기간">
                {weeks.map((week) => <button
                  key={week}
                  role="option"
                  aria-selected={week === selectedWeek}
                  onClick={() => { setSelectedWeek(week); setWeekPickerOpen(false) }}
                >
                  {week}
                </button>)}
              </div>}
            </div>
            <h1 className={screen.heading}>이번 주, AI가 당신에 대해 이해한 것이<br />이렇게 달라졌습니다.</h1>
          </header>
          <button className={screen.buttonGhost} onClick={() => setModal('cleanup')}><Clock3 size={14} />47초 정리</button>
        </div>

        <div className={styles.summaryBar}>
          <div><span>이번 주 Memory OS가 대부분을 정리했습니다.</span><strong>전체 {workspace.memoryCount}개 중 94% 자동 정리 · 직접 판단 {pending.length}건</strong></div>
          <button className={screen.buttonGhost} onClick={() => setModal('review')}>빠르게 판단하기 <ArrowRight size={14} /></button>
        </div>

        <div className={styles.sectionHead}><span>가장 중요한 변화</span><b>1건</b><div /></div>
        <div className={styles.feed} id="changes-feed">
          {(showAll ? workspace.changes : workspace.changes.slice(0, 1)).map((item) => (
            <article key={item.id} className={`${styles.changeCard} ${item.status === 'resolved' ? styles.resolved : ''}`}>
              {item.id !== 'flutter-change' && <div className={styles.cardMeta}><span>{kindLabel[item.kind]}</span><small>{item.meta}</small></div>}
              <h2>{item.id === 'flutter-change' ? 'Flutter를 선호하지 않습니다.' : item.title}</h2><p>{item.description}</p>
              {item.evidence.length > 0 && <ul>{item.evidence.slice(0, 2).map((entry) => <li key={entry}>{entry}</li>)}</ul>}
              <div className={styles.cardActions}>
                {item.status === 'resolved' ? <span className={styles.done}><Check size={13} /> 반영됨</span> : <>
                  {item.id === 'flutter-change' ? <>
                    <button className={styles.acceptButton} aria-label="이 변화가 맞음" onClick={() => void resolveChange(item.id, 'accept')}><Check size={18} aria-hidden="true" /></button>
                    <button className={`${screen.buttonGhost} ${styles.detailsButton}`} onClick={() => setModal('diff')}>변경 내용 보기</button>
                  </> : <>
                    <button className={screen.button} onClick={() => void resolveChange(item.id, 'accept')}>{item.kind === 'fading' ? '지금 보관' : item.kind === 'duplicate' ? '하나로 병합' : '조건 저장'}</button>
                    <button className={screen.textButton} onClick={() => void resolveChange(item.id, 'reject')}>아직 유효해요</button>
                  </>}
                </>}
              </div>
            </article>
          ))}
        </div>
        <button className={styles.disclosure} aria-expanded={showAll} aria-controls="changes-feed" onClick={() => setShowAll((value) => !value)}>{showAll ? '간단히 보기' : `나머지 ${workspace.changes.length - 1}개 보기`}<ArrowRight size={14} /></button>
      </div>

      {modal === 'diff' && <div className={styles.backdrop} onMouseDown={() => setModal(null)}><div className={styles.dialog} role="dialog" aria-modal="true" aria-label="이해 업데이트 제안" onMouseDown={(event) => event.stopPropagation()}>
        <div className={styles.dialogTop}><span>이해 업데이트 제안</span><button autoFocus aria-label="닫기" onClick={() => setModal(null)}><X size={16} /></button></div>
        <h2>AI가 당신에 대한 이해를<br />이렇게 바꾸려 합니다.</h2>
        <div className={styles.diff}><div><span>BEFORE</span><p>{change.before}</p></div><ArrowRight size={18} /><div><span>AFTER</span><p>{change.after}</p></div></div>
        <p className={styles.evidence}>근거 {change.evidence.length + 11}개 · 최근 90일 대화에서 수집</p>
        {showEvidence && <ul className={styles.dialogEvidence}>{change.evidence.map((item) => <li key={item}>{item}</li>)}</ul>}
        <div className={styles.dialogActions}><button className={screen.button} onClick={async () => { await resolveChange(change.id, 'accept'); setModal(null) }}>이 이해를 승인</button><button className={screen.buttonGhost} onClick={() => setModal(null)}>기존 유지</button><button className={screen.textButton} aria-expanded={showEvidence} onClick={() => setShowEvidence((value) => !value)}>{showEvidence ? '근거 접기' : '근거 더 보기'}</button></div>
      </div></div>}

      {modal === 'review' && <div className={styles.backdrop} onMouseDown={() => setModal(null)}><div className={`${styles.dialog} ${styles.reviewDialog}`} role="dialog" aria-modal="true" aria-label="판단 필요" onMouseDown={(event) => event.stopPropagation()}>
        <div className={styles.dialogTop}><span>판단 필요 · 1 / 2</span><button autoFocus onClick={() => setModal(null)}>나중에</button></div><h2>창업은 B2C 위주로 하고 싶음</h2><span className={styles.outdated}>아마도 낡은 기억</span><p>8개월 전에 만들어진 기억입니다. 그 이후 B2B 아이디어를 7번 탐색하고 협업 SaaS를 3번 검토했습니다.</p><div className={styles.dialogActions}><button className={screen.button} onClick={() => setModal(null)}>맞아요, 약화시켜요</button><button className={screen.buttonGhost} onClick={() => setModal(null)}>아직 유효해요</button></div>
      </div></div>}

      {modal === 'cleanup' && <div className={styles.cleanupBackdrop} role="dialog" aria-modal="true" aria-label="기억 정리"><div className={styles.cleanupTop}><span>MEMORY CLEANUP</span><b>{cleanupIndex + 1} / {cleanup.length}</b></div><div className={styles.cleanupStack}><i /><i /><div className={styles.cleanupCard}><span>{cleanup[cleanupIndex].category} · {cleanup[cleanupIndex].ageLabel}</span><h2>{cleanup[cleanupIndex].text}</h2><p>최근 답변에 미치는 영향이 낮아졌습니다. 이 기억을 계속 유지할까요?</p><div><button autoFocus className={screen.buttonGhost} onClick={advanceCleanup}>← 잊어도 돼</button><button className={screen.button} onClick={advanceCleanup}>유지 →</button></div></div></div><button className={screen.textButton} onClick={() => setModal(null)}>그만하기 · 나머지는 AI가 알아서</button></div>}
    </section>
  )
}

